local _, WFJ = ...
WFJ.Data.add("book", {
  ["7114ab5089f7cdbf"] = { "言うまでもないことだが、我々――Kargathに駐屯する者たちは、この任務にすっかり満足している。ここでは強くあり続ける。軟弱になれば死ぬからだ。\n\nそして、それ以外のやり方など望みはしない。\n\nNeeka Bloodscar\nKargath、主任Scout", "." },
  ["711ab8e1c07f2225"] = { "その後の年月、StormwindがStonemasons' Guildを裏切ってから、Sir Erlgadinは王国における貴族の役割に苦々しい思いを抱くようになった。父の血筋によって得たHouse of Noblesでの地位を、彼はもはや守りたいとは思わなかった。\n\nだが話がそれた。この物語の目的は、政治論文や伝記となることではない。これは、Stranglethornの緑の丘で大物狩りをした私の経験の記録である……。", "." },
  ["712343b0a36c48a1"] = { "戦争はKhaz Modan、Lordaeron、そしてAzerothそのものの大陸にわたって激しく続いた。北方遠征の一環として、HordeはQuel'Thalasの辺境を焼き払うことに成功し、それによってelvesはAllianceの大義に最終的に身を投じることとなった。Lordaeronの大きな都市や町は、この戦いによって破壊され荒廃した。援軍もなく圧倒的に不利な状況にもかかわらず、Lotharと同盟者たちは敵を食い止めることに成功した。", "." },
  ["71479c7efa3ab91b"] = { "このArmor Markerは、革または布の防具1点と引き換えられる。Eastvale Logging Camp内のTimberlain家で交換できる。", "." },
  ["7166ce29e3db1085"] = { "Refined Ore - Thelsamarに、私がしばらく共に修行したドワーフの鍛冶屋がいる。名をBailor Stonehandという。彼はとても特別な合金を作っていて、それがあなたの武器にぴったりだと思う。Ironforgeにいる間に合金の荷が届くはずだったのだが、いまだに彼から何の便りもない。\n\n彼を見つけて、荷のことを確かめてくれ。もし彼がもうLoch Modanにいないのなら、せめて私の昔の師に何があったのかを知りたい。", "." },
  ["716e6a76c4f923d9"] = { "トーレンのシャーマンやドルイドの庇護のもとで経路を通じてこれらの精霊が起こす騒ぎが、彼らの気をそらしているものと考えざるを得ません。トーレンはStonetalon MountainsのVenture Companyを深刻な脅威と見なしているのですから。\n\n脅威であろうとなかろうと、我々は同盟者を助けねばなりません。\n\nLydon、あなたは毒物について幅広い知識をお持ちです。Stonetalonのゴブリンたちのあいだに伝染病を広めるのに使えるものを考案できませんか?\n\n学究の敬意を込めて、\nP. Zamah", "." },
  ["7170ee119f48cf60"] = { "約16,000年前（ナイトエルフが愚かにもBurning Legionの怒りを招くはるか以前）、トロールはKalimdor（当時は1つの大陸だった）の大部分を支配していた。双子のトロール帝国が存在した――南東のジャングルのGurubashi Empireと、中部の森林地帯のAmani Empireである。", "." },
  ["71ba17c63c56181b"] = { "AjeckとSir Erlgadinは私の両脇を固めて武器を構え、我々は海を背にした。Barnilは観念したようにため息をつき、斧を抜いた。Lashtailsはもう目前に迫っていた。着実だった歩みは緩やかになっていた。奴らは今、獲物に忍び寄っていた。我々を追い詰めたと分かっていたからだ。", "." },
  ["71dc229643105a98"] = { "われらの世界は歴史に満ちている。新しき種族と古き種族の歴史。とうに終わった戦争と、いまだくすぶる戦争の背後にある歴史。\n\n天より訪れた神々の歴史。そして大地に眠る、より古き神々の歴史。\n\n今こそ私はそれらの存在――Old Godsについて語ろう。世界がまだ新しかった頃、Azerothの全土に棲み、猛威を振るった者たちである。", "." },
  ["71e2d8492f6d3e51"] = { "Earthmotherは、清らかな子らの勇敢な心に狩りへの愛を授けた。最初の夜明けの生き物たちは獰猛で荒々しかったからである。彼らはEarthmotherから身を隠し、影や大地の荒れた場所に安らぎを見いだした。Shu'haloはこれらの獣を見つけられる限りどこまでも狩り、Earthmotherの祝福によって飼い慣らした。", "." },
  ["71f88e19d13d4ae9"] = { "だが、あいつの言うとおりだった。我々は破滅する。Agamand家の血筋は絶えるだろう。まだ生きてはいるが、じきに死ぬことは分かっている。\n\n恐れてはいないし、家族とともに残ったことを後悔してもいない。だが、最後に思うのは君のことだ。\n\n生き延びてくれ、愛しいYvette。そうすれば私は安らかに眠れる。\n-Thurman", "." },
})
